import json
from pathlib import Path
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment
from openpyxl.utils import get_column_letter as CL
A = Path("artifacts"); r = json.loads((A/"research_results.json").read_text()); bm = json.loads((A/"benchmarks.json").read_text()) if (A/"benchmarks.json").exists() else None
M = r["oos_comparison"]["metrics"]; N = ["gaussian","gaussian_copula","t_copula","fhs","cvae"]
L = {"gaussian":"Gaussian","gaussian_copula":"Gaussian copula","t_copula":"Student-t copula","fhs":"FHS (GJR-GARCH)","cvae":"Conditional VAE"}
F = "Arial"; H = Font(name=F, bold=True, color="FFFFFF"); HF = PatternFill("solid", fgColor="1F3A5F"); B = Font(name=F); BL = Font(name=F, color="0000FF")
wb = Workbook()
def sheet(name, head, rows, widths=None, note=None, fmts=None):
    ws = wb.create_sheet(name); ws.append(head)
    for c in ws[1]: c.font, c.fill, c.alignment = H, HF, Alignment(wrap_text=True, vertical="center")
    for row in rows: ws.append(row)
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.font = BL if isinstance(c.value,(int,float)) else B
            if fmts and c.column in fmts and isinstance(c.value,(int,float)): c.number_format = fmts[c.column]
    for i in range(1, len(head)+1): ws.column_dimensions[CL(i)].width = (widths or {}).get(i, 18)
    ws.freeze_panes = "B2"
    if note: ws.cell(ws.max_row+2, 1, note).font = Font(name=F, italic=True)
    return ws
# Summary
ws = wb.active; ws.title = "Summary"
syn = r["dataset"]["synthetic"]
def _wins(fn):
    v = {m: fn(m) for m in N}; return L[min(v, key=v.get)]
wass = _wins(lambda m: M[m]["wasserstein_mean"]); corr = _wins(lambda m: M[m]["corr_frobenius"]); es = _wins(lambda m: abs(M[m]["es95_cum"]["NIFTY"]["model"]-M[m]["es95_cum"]["NIFTY"]["real"]))
cvals = {m: c0["report"][0]["share_within_tolerance"] for m, c0 in r["constraint_satisfaction"].items()}; cons_best = L[max(cvals, key=cvals.get)]
exc = {m: r["backtest"]["results"][m]["0.95"]["kupiec"]["p_value"] for m in N}; calibrated = ", ".join(L[m] for m in N if exc[m] >= 0.05) or "none"
lines = [("CRASHLAB — build status and results",None),
 ("Data","SYNTHETIC development data - not evidence about real markets." if syn else f"REAL market data ({r['dataset']['source']}), {r['dataset']['start']} to {r['dataset']['end']}; unofficial source, subject to provider terms."),
 ("Source of numbers","artifacts/research_results.json (generated by the pipeline); blue cells are values copied from it, black cells are formulas."),
 ("Train/val/test rows",f"{r['split']['n_train']} / {r['split']['n_val']} / {r['split']['n_test']} (chronological; test from {r['split']['test_start']})"),
 ("cVAE size",f"{r['cvae']['params']:,} parameters, {len(r['cvae']['history'])} epochs, {r['cvae']['train_seconds']:.0f}s CPU, single seed"),
 ("Best marginal fit (Wasserstein)",wass),("Best correlation fit",corr),("Best NIFTY ES95 fit",es),("Best constraint satisfaction (NIFTY)",cons_best),
 ("95% VaR Kupiec not rejected",calibrated),
 ("Caveat","FHS is conditioned on the volatility state at each forecast origin; the other models are not (see report section 6)."),
 ("Ablations","Present." if r.get("ablations") else "Not run in this build.")]
for i,(a,b) in enumerate(lines,1):
    ws.cell(i,1,a).font = Font(name=F, bold=True, size=13 if i==1 else 11); 
    if b: ws.cell(i,2,b).font = B; ws.cell(i,2).alignment = Alignment(wrap_text=True, vertical="top")
ws.column_dimensions["A"].width = 24; ws.column_dimensions["B"].width = 100
# Scorecard with formulas
metrics = [("Mean Wasserstein (sd units)", lambda m: M[m]["wasserstein_mean"]),("Correlation RMS error", lambda m: M[m]["corr_frobenius"]),
 ("|Tail-dep error| NIFTY-BANK", lambda m: abs(M[m]["tail_dep_lower_q05"]["NIFTY-BANK"]["model"]-M[m]["tail_dep_lower_q05"]["NIFTY-BANK"]["real"])),
 ("|Joint-exceedance error|", lambda m: abs(M[m]["joint_exceed_nifty_down_inr_weak"]["model"]-M[m]["joint_exceed_nifty_down_inr_weak"]["real"])),
 ("|Vol-clustering ACF error|", lambda m: abs(M[m]["vol_clustering_acf1_sq_nifty"]["model"]-M[m]["vol_clustering_acf1_sq_nifty"]["real"])),
 ("|ES95 error| NIFTY 10d", lambda m: abs(M[m]["es95_cum"]["NIFTY"]["model"]-M[m]["es95_cum"]["NIFTY"]["real"]))]
ws = sheet("OOS Scorecard", ["Metric (lower = better)"]+[L[m] for m in N]+["Best model"], [[n]+[round(f(m),4) for m in N] for n,f in metrics], {1:34,7:20}, "Best model is computed by formula. Overlapping test windows: effective sample ~n/10. No single metric proves superiority.", {2:"0.000",3:"0.000",4:"0.000",5:"0.000",6:"0.000"})
for i in range(2, 2+len(metrics)):
    ws.cell(i,7, f"=INDEX($B$1:$F$1,MATCH(MIN(B{i}:F{i}),B{i}:F{i},0))").font = Font(name=F, bold=True)
c = r["constraint_satisfaction"]
sheet("Constraints", ["Model","Mode","NIFTY median (target -12%)","NIFTY within tol.","USDINR median (target +3%)","USDINR within tol."],
 [[L[m],c[m]["conditioning"],c[m]["report"][0]["realised_median_simple"],c[m]["report"][0]["share_within_tolerance"],c[m]["report"][1]["realised_median_simple"],c[m]["report"][1]["share_within_tolerance"]] for m in N],
 {1:22,2:18,3:24,4:18,5:24,6:18}, "10 days, extreme regime, 1,000 paths. cVAE conditioned natively; baselines by analog selection (no path altered).", {3:"0.0%",4:"0%",5:"0.0%",6:"0%"})
b = r["backtest"]; rows=[]
for a in ("0.95","0.99"):
    for m in N:
        x=b["results"][m][a]; rows.append([f"{float(a)*100:.0f}%",L[m],x["kupiec"]["exceedances"],round(x["kupiec"]["expected"],1),x["kupiec"]["p_value"],x["christoffersen"]["p_ind"],x["christoffersen"]["p_cc"],x["acerbi_szekely"]["z2"],x["acerbi_szekely"].get("p_value")])
ws = sheet("Backtests", ["Level","Model","Exceedances","Expected","Kupiec p","Christoffersen ind. p","Cond. coverage p","A-S Z2","A-S MC p","Kupiec at 5%?"], rows, {2:22,10:16}, f"{b['n_windows']} non-overlapping 5-day windows; low power at 99%.", {5:"0.000",6:"0.000",7:"0.000",8:"0.00",9:"0.000"})
for i in range(2, 2+len(rows)): ws.cell(i,10, f'=IF(E{i}<0.05,"Rejected","Not rejected")').font = B
sheet("Ablations", ["Variant","Val loss","Epochs","OOS Wasserstein","OOS corr. error","Tail dep. NIFTY-BANK","Train s"],
 [[a["variant"],a["best_val_loss"],a["epochs_run"],a["oos_wasserstein_mean"],a["oos_corr_frobenius"],a["oos_tail_dep_nifty_bank"],a["train_seconds"]] for a in r.get("ablations", [])],
 {1:38}, f"Single seed - small differences are noise. Real tail dependence in test: {M['fhs']['tail_dep_lower_q05']['NIFTY-BANK']['real']:.2f}. Val losses not comparable for tail-aware.", {2:"0.0",4:"0.000",5:"0.000",6:"0.00",7:"0"})
if bm: sheet("Benchmarks", ["Model","1,000 paths (s)","paths/s @1k","10,000 paths (s)","paths/s @10k"],
 [[L[m],v["1000"]["median_seconds"],v["1000"]["scenarios_per_second"],v["10000"]["median_seconds"],v["10000"]["scenarios_per_second"]] for m,v in bm["models"].items()],
 {1:22}, f"Peak RSS {bm['peak_rss_mb']:.0f} MB, {bm['cpu_count']} CPUs; measured on the sandbox only.", {2:"0.000",3:"#,##0",4:"0.00",5:"#,##0"})
sheet("Open Items", ["Item","Status","Detail"], [["Real-market data","Done" if not syn else "Not done","Yahoo Finance history" if not syn else "Synthetic only"],["Live deployment","Not done","Needs your hosting accounts; guide in docs/DEPLOYMENT.md"],
 ["Docker images","Not verified","Never built in the build sandbox; compose file validates"],["Ablations","Done" if r.get("ablations") else "Not run","python -m crashlab.pipeline --no-synthetic"],["Statistical caveats","Known","One dataset, one seed, small backtest samples"]],
 {1:24,2:16,3:70})
wb.save("docs/CRASHLAB_results.xlsx")
